 EXEC(N'CREATE OR ALTER FUNCTION dbo.ClubRoleRank(@ClubId int,@UserId int) RETURNS int AS
BEGIN
 -- 4 Owner, 3 Manager, 2 Reception, 1 Coach, 0 none. GameOn operators act as owners of every club.
 IF EXISTS(SELECT 1 FROM dbo.PaymentOperators WHERE UserId=@UserId) RETURN 4;
 RETURN COALESCE((SELECT CASE Role WHEN ''Owner'' THEN 4 WHEN ''Manager'' THEN 3 WHEN ''Reception'' THEN 2 WHEN ''Coach'' THEN 1 END FROM dbo.ClubStaff WHERE ClubId=@ClubId AND UserId=@UserId),0);
END;');
 EXEC(N'CREATE OR ALTER FUNCTION dbo.IsPro(@UserId int) RETURNS bit AS
BEGIN
 RETURN CASE WHEN EXISTS(SELECT 1 FROM dbo.Memberships WHERE UserId=@UserId AND Tier=''Pro'' AND StartsAt<=SYSUTCDATETIME() AND EndsAt>SYSUTCDATETIME()) THEN 1 ELSE 0 END;
END;');
 EXEC(N'CREATE OR ALTER FUNCTION dbo.ToBeirut(@Utc datetime2(0)) RETURNS datetime2(0) AS
BEGIN
 RETURN CONVERT(datetime2(0),(@Utc AT TIME ZONE ''UTC'') AT TIME ZONE ''Middle East Standard Time'');
END;');
 EXEC(N'CREATE OR ALTER FUNCTION dbo.FromBeirut(@Local datetime2(0)) RETURNS datetime2(0) AS
BEGIN
 RETURN CONVERT(datetime2(0),(@Local AT TIME ZONE ''Middle East Standard Time'') AT TIME ZONE ''UTC'');
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.LoyaltyPost @UserId int,@Points int,@Reason varchar(16),@RefType varchar(12),@RefId bigint,@Note nvarchar(200)=NULL AS
BEGIN
 SET NOCOUNT ON;
 -- Caller owns the transaction. Each (reason, reference) earns or spends once.
 IF EXISTS(SELECT 1 FROM dbo.LoyaltyLedger WHERE Reason=@Reason AND RefType=@RefType AND RefId=@RefId AND UserId=@UserId) RETURN;
 IF NOT EXISTS(SELECT 1 FROM dbo.LoyaltyAccounts WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@UserId) INSERT dbo.LoyaltyAccounts(UserId) VALUES(@UserId);
 DECLARE @Balance int=(SELECT Points FROM dbo.LoyaltyAccounts WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@UserId);
 IF @Balance+@Points<0 SET @Points=-@Balance; -- a reversal never drives the balance negative
 IF @Points=0 RETURN;
 UPDATE dbo.LoyaltyAccounts SET Points=Points+@Points,LifetimePoints=LifetimePoints+CASE WHEN @Points>0 AND @Reason<>''Reversal'' THEN @Points ELSE 0 END WHERE UserId=@UserId;
 INSERT dbo.LoyaltyLedger(UserId,Points,BalanceAfter,Reason,RefType,RefId,Note) VALUES(@UserId,@Points,@Balance+@Points,@Reason,@RefType,@RefId,@Note);
END;');
 EXEC(N'CREATE OR ALTER TRIGGER dbo.LoyaltyGamePlayed ON dbo.EventAttendance AFTER INSERT,UPDATE AS
BEGIN
 SET NOCOUNT ON;
 -- Points for a game only when the host AND the player both confirm attendance (neither can earn alone).
 DECLARE @G int,@U int;
 DECLARE r CURSOR LOCAL FAST_FORWARD FOR SELECT i.GameId,i.UserId FROM inserted i WHERE i.HostMark=''Attended'' AND i.PlayerMark=''Attended'';
 OPEN r; FETCH NEXT FROM r INTO @G,@U;
 WHILE @@FETCH_STATUS=0
 BEGIN
  EXEC dbo.LoyaltyPost @U,50,''GamePlayed'',''Game'',@G,N''Played a GameOn game'';
  FETCH NEXT FROM r INTO @G,@U;
 END;
 CLOSE r; DEALLOCATE r;
END;');
 EXEC(N'CREATE OR ALTER TRIGGER dbo.ApprovalRequiredParticipation ON dbo.Participations AFTER INSERT AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.GamesAndEvents g ON g.EventId=i.GameId
  WHERE g.JoinMode=''Approval'' AND i.UserId<>g.HostUserId
   AND NOT EXISTS(SELECT 1 FROM dbo.GameJoinRequests r WHERE r.GameId=i.GameId AND r.UserId=i.UserId AND r.Status=''Approved''))
  THROW 50003,''The host must approve your request before you can take a place.'',1;
END;');
 EXEC(N'CREATE OR ALTER TRIGGER dbo.ApprovalRequiredWaitlist ON dbo.Waitlists AFTER INSERT AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.GamesAndEvents g ON g.EventId=i.GameId
  WHERE g.JoinMode=''Approval'' AND NOT EXISTS(SELECT 1 FROM dbo.GameJoinRequests r WHERE r.GameId=i.GameId AND r.UserId=i.UserId AND r.Status=''Approved''))
  THROW 50003,''The host must approve your request before you can join the waitlist.'',1;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.SetGameAccess @GameId int,@HostUserId int,@Visibility varchar(8),@JoinMode varchar(8) AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @Visibility NOT IN(''Public'',''Private'') OR @JoinMode NOT IN(''Instant'',''Approval'') THROW 50002,''Choose who can see and join this game.'',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Host int=(SELECT HostUserId FROM dbo.GamesAndEvents WITH(UPDLOCK,HOLDLOCK) WHERE EventId=@GameId);
  IF @Host IS NULL THROW 50001,''Game not found.'',1;
  IF @Host<>@HostUserId THROW 50003,''Only the host can change this.'',1;
  -- Private games always need the host''s approval or an invite link.
  IF @Visibility=''Private'' SET @JoinMode=''Approval'';
  UPDATE dbo.GamesAndEvents SET Visibility=@Visibility,JoinMode=@JoinMode,
   InviteCode=CASE WHEN @Visibility=''Private'' THEN COALESCE(InviteCode,UPPER(LEFT(REPLACE(CONVERT(varchar(36),NEWID()),''-'',''''),10))) ELSE InviteCode END
  WHERE EventId=@GameId;
  -- Players already in keep their places: record them as approved.
  INSERT dbo.GameJoinRequests(GameId,UserId,Status,DecidedBy,DecidedAt)
  SELECT p.GameId,p.UserId,''Approved'',@HostUserId,SYSUTCDATETIME() FROM dbo.Participations p WHERE p.GameId=@GameId AND p.UserId<>@Host
   AND NOT EXISTS(SELECT 1 FROM dbo.GameJoinRequests r WHERE r.GameId=p.GameId AND r.UserId=p.UserId);
  INSERT dbo.GameJoinRequests(GameId,UserId,Status,DecidedBy,DecidedAt)
  SELECT w.GameId,w.UserId,''Approved'',@HostUserId,SYSUTCDATETIME() FROM dbo.Waitlists w WHERE w.GameId=@GameId
   AND NOT EXISTS(SELECT 1 FROM dbo.GameJoinRequests r WHERE r.GameId=w.GameId AND r.UserId=w.UserId);
  COMMIT;
  SELECT Visibility,JoinMode,InviteCode FROM dbo.GamesAndEvents WHERE EventId=@GameId;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.GetGameAccess @GameId int,@UserId int=NULL,@InviteCode char(10)=NULL AS
BEGIN
 SET NOCOUNT ON;
 SELECT g.Visibility,g.JoinMode,CASE WHEN g.HostUserId=@UserId THEN g.InviteCode END AS InviteCode,
  CAST(CASE WHEN g.Visibility=''Public'' OR g.HostUserId=@UserId OR (@InviteCode IS NOT NULL AND g.InviteCode=@InviteCode)
   OR EXISTS(SELECT 1 FROM dbo.Participations p WHERE p.GameId=g.EventId AND p.UserId=@UserId)
   OR EXISTS(SELECT 1 FROM dbo.Waitlists w WHERE w.GameId=g.EventId AND w.UserId=@UserId)
   OR EXISTS(SELECT 1 FROM dbo.GameJoinRequests r WHERE r.GameId=g.EventId AND r.UserId=@UserId) THEN 1 ELSE 0 END AS bit) AS CanView,
  (SELECT Status FROM dbo.GameJoinRequests r WHERE r.GameId=g.EventId AND r.UserId=@UserId) AS MyRequest,
  g.Capacity-(SELECT COUNT(*) FROM dbo.Participations p WHERE p.GameId=g.EventId) AS FreeSpots,
  (SELECT COUNT(*) FROM dbo.Waitlists w WHERE w.GameId=g.EventId) AS WaitlistCount
 FROM dbo.GamesAndEvents g WHERE g.EventId=@GameId;
 -- Pending requests (host only)
 SELECT r.UserId,u.DisplayName,r.Message,r.CreatedAt,CAST(dbo.IsPro(r.UserId) AS bit) AS IsPro,
  (SELECT COUNT(*) FROM dbo.EventCompletions c JOIN dbo.EventAttendance a ON a.GameId=c.GameId WHERE a.UserId=r.UserId AND a.HostMark=''Attended'' AND a.PlayerMark=''Attended'') AS GamesPlayed
 FROM dbo.GameJoinRequests r JOIN dbo.Users u ON u.UserId=r.UserId JOIN dbo.GamesAndEvents g ON g.EventId=r.GameId
 WHERE r.GameId=@GameId AND r.Status=''Pending'' AND g.HostUserId=@UserId ORDER BY r.CreatedAt;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.ListPrivateGamesHidden @UserId int=NULL AS
BEGIN
 SET NOCOUNT ON;
 -- Private games the caller may NOT see in discovery (API filters these out).
 SELECT g.EventId AS GameId FROM dbo.GamesAndEvents g WHERE g.Visibility=''Private'' AND g.StartsAt>DATEADD(day,-1,SYSUTCDATETIME())
  AND (@UserId IS NULL OR (g.HostUserId<>@UserId AND NOT EXISTS(SELECT 1 FROM dbo.Participations p WHERE p.GameId=g.EventId AND p.UserId=@UserId)
   AND NOT EXISTS(SELECT 1 FROM dbo.GameJoinRequests r WHERE r.GameId=g.EventId AND r.UserId=@UserId)));
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.RequestToJoin @GameId int,@UserId int,@Message nvarchar(200)=NULL,@InviteCode char(10)=NULL AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Host int,@Mode varchar(8),@Vis varchar(8),@Code char(10),@State varchar(12),@Start datetime2(3);
  SELECT @Host=HostUserId,@Mode=JoinMode,@Vis=Visibility,@Code=InviteCode,@State=GameStatus,@Start=StartsAt FROM dbo.GamesAndEvents WITH(UPDLOCK,HOLDLOCK) WHERE EventId=@GameId;
  IF @Host IS NULL THROW 50001,''Game not found.'',1;
  IF @UserId=@Host THROW 50002,''You are the host.'',1;
  IF @State<>''Open'' OR @Start<=SYSUTCDATETIME() THROW 50002,''This game is no longer open.'',1;
  IF @Vis=''Private'' AND (@InviteCode IS NULL OR @InviteCode<>@Code) AND NOT EXISTS(SELECT 1 FROM dbo.Friendships f WHERE f.Status=''Accepted'' AND f.UserLow=IIF(@UserId<@Host,@UserId,@Host) AND f.UserHigh=IIF(@UserId<@Host,@Host,@UserId))
   THROW 50003,''This is a private game. Ask the host for the invite link.'',1;
  DECLARE @Auto bit=CASE WHEN @Mode=''Instant'' OR (@InviteCode IS NOT NULL AND @InviteCode=@Code) THEN 1 ELSE 0 END;
  MERGE dbo.GameJoinRequests AS t USING (SELECT @GameId g,@UserId u) s ON t.GameId=s.g AND t.UserId=s.u
  -- A declined player cannot re-request (no spamming the host) unless they have the invite link.
  WHEN MATCHED AND (t.Status=''Withdrawn'' OR (t.Status=''Declined'' AND @Auto=1)) THEN UPDATE SET Status=IIF(@Auto=1,''Approved'',''Pending''),Message=@Message,
   DecidedBy=IIF(@Auto=1,@Host,NULL),DecidedAt=IIF(@Auto=1,SYSUTCDATETIME(),NULL),CreatedAt=SYSUTCDATETIME()
  WHEN NOT MATCHED THEN INSERT(GameId,UserId,Status,Message,DecidedBy,DecidedAt) VALUES(@GameId,@UserId,IIF(@Auto=1,''Approved'',''Pending''),@Message,IIF(@Auto=1,@Host,NULL),IIF(@Auto=1,SYSUTCDATETIME(),NULL));
  IF @Auto=0 AND (SELECT Status FROM dbo.GameJoinRequests WHERE GameId=@GameId AND UserId=@UserId)=''Pending''
   INSERT dbo.Notifications(UserId,GameId,Title,Body) VALUES(@Host,@GameId,N''New request to join'',N''A player asked to join your game. Open it to approve or decline.'');
  COMMIT;
  SELECT Status FROM dbo.GameJoinRequests WHERE GameId=@GameId AND UserId=@UserId;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.DecideJoinRequest @GameId int,@HostUserId int,@UserId int,@Approve bit AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  IF NOT EXISTS(SELECT 1 FROM dbo.GamesAndEvents WITH(UPDLOCK,HOLDLOCK) WHERE EventId=@GameId AND HostUserId=@HostUserId) THROW 50003,''Only the host can decide.'',1;
  UPDATE dbo.GameJoinRequests SET Status=IIF(@Approve=1,''Approved'',''Declined''),DecidedBy=@HostUserId,DecidedAt=SYSUTCDATETIME() WHERE GameId=@GameId AND UserId=@UserId AND Status=''Pending'';
  IF @@ROWCOUNT=0 THROW 50004,''This request was already handled.'',1;
  INSERT dbo.Notifications(UserId,GameId,Title,Body) VALUES(@UserId,@GameId,IIF(@Approve=1,N''You were approved!'',N''Request declined''),
   IIF(@Approve=1,N''The host approved you. Open the game and confirm your place with the $1 deposit before the spots fill.'',N''The host could not take you this time. Find another game in Discover.''));
  COMMIT;
  SELECT IIF(@Approve=1,''Approved'',''Declined'') AS Status;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.CreateClub @OperatorId int,@VenueId int,@Name nvarchar(120),@OwnerUserId int,@IsPartner bit=0,@ProDiscountPct tinyint=0 AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF NOT EXISTS(SELECT 1 FROM dbo.PaymentOperators WHERE UserId=@OperatorId) THROW 50003,''Only GameOn operators can onboard clubs.'',1;
 IF NULLIF(TRIM(@Name),N'''') IS NULL OR @ProDiscountPct>50 THROW 50002,''Enter the club name and a Pro discount of 0-50%.'',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Venues WHERE VenueId=@VenueId AND ListingStatus<>''Demo'') THROW 50002,''Choose a real directory venue.'',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Users WHERE UserId=@OwnerUserId) THROW 50002,''The owner must have a GameOn account.'',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  INSERT dbo.Clubs(Name,VenueId,IsPartner,ProDiscountPct,CreatedBy) VALUES(TRIM(@Name),@VenueId,@IsPartner,@ProDiscountPct,@OperatorId);
  DECLARE @Club int=SCOPE_IDENTITY();
  INSERT dbo.ClubStaff(ClubId,UserId,Role,AddedBy) VALUES(@Club,@OwnerUserId,''Owner'',@OperatorId);
  INSERT dbo.Notifications(UserId,Title,Body) VALUES(@OwnerUserId,N''Your club is on GameOn'',N''Open Club manager to add courts, opening hours and prices.'');
  COMMIT;
  SELECT @Club AS ClubId;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.SetClubStaff @ClubId int,@ActorId int,@UserId int,@Role varchar(12)=NULL AS
BEGIN
 SET NOCOUNT ON;
 IF dbo.ClubRoleRank(@ClubId,@ActorId)<4 THROW 50003,''Only the club owner can manage staff.'',1;
 IF @UserId=@ActorId THROW 50002,''You cannot change your own role.'',1;
 IF @Role IS NOT NULL AND @Role NOT IN(''Manager'',''Reception'',''Coach'') THROW 50002,''Choose Manager, Reception or Coach.'',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Users WHERE UserId=@UserId) THROW 50002,''No GameOn account with that email.'',1;
 IF @Role IS NULL DELETE dbo.ClubStaff WHERE ClubId=@ClubId AND UserId=@UserId AND Role<>''Owner'';
 ELSE MERGE dbo.ClubStaff AS t USING (SELECT @ClubId c,@UserId u) s ON t.ClubId=s.c AND t.UserId=s.u
  WHEN MATCHED AND t.Role<>''Owner'' THEN UPDATE SET Role=@Role
  WHEN NOT MATCHED THEN INSERT(ClubId,UserId,Role,AddedBy) VALUES(@ClubId,@UserId,@Role,@ActorId);
 SELECT ''Saved'' AS Status;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.SaveCourt @ClubId int,@ActorId int,@CourtId int=NULL,@Name nvarchar(80),@SubtypeId int,@SlotMinutes smallint,@OpenHour tinyint,@CloseHour tinyint,
 @BasePrice decimal(10,2),@PeakPrice decimal(10,2),@PeakStartHour tinyint,@PeakEndHour tinyint,@IsActive bit=1 AS
BEGIN
 SET NOCOUNT ON;
 IF dbo.ClubRoleRank(@ClubId,@ActorId)<3 THROW 50003,''Managers and owners can edit courts.'',1;
 IF NULLIF(TRIM(@Name),N'''') IS NULL OR @SlotMinutes NOT IN(30,60,90,120) OR @OpenHour>=@CloseHour OR @CloseHour>24 OR @PeakStartHour>@PeakEndHour OR @PeakEndHour>24 OR @BasePrice<0 OR @PeakPrice<0
  THROW 50002,''Check the court name, hours and prices.'',1;
 IF @CourtId IS NULL
 BEGIN
  INSERT dbo.Courts(ClubId,Name,SubtypeId,SlotMinutes,OpenHour,CloseHour,BasePrice,PeakPrice,PeakStartHour,PeakEndHour,IsActive)
  VALUES(@ClubId,TRIM(@Name),@SubtypeId,@SlotMinutes,@OpenHour,@CloseHour,@BasePrice,@PeakPrice,@PeakStartHour,@PeakEndHour,@IsActive);
  SET @CourtId=SCOPE_IDENTITY();
 END
 ELSE
 BEGIN
  UPDATE dbo.Courts SET Name=TRIM(@Name),SubtypeId=@SubtypeId,SlotMinutes=@SlotMinutes,OpenHour=@OpenHour,CloseHour=@CloseHour,BasePrice=@BasePrice,PeakPrice=@PeakPrice,
   PeakStartHour=@PeakStartHour,PeakEndHour=@PeakEndHour,IsActive=@IsActive,Revision=Revision+1 WHERE CourtId=@CourtId AND ClubId=@ClubId;
  IF @@ROWCOUNT=0 THROW 50001,''Court not found.'',1;
 END;
 INSERT dbo.VenueSubtypes(VenueId,SubtypeId) SELECT c.VenueId,@SubtypeId FROM dbo.Clubs c WHERE c.ClubId=@ClubId AND NOT EXISTS(SELECT 1 FROM dbo.VenueSubtypes vs WHERE vs.VenueId=c.VenueId AND vs.SubtypeId=@SubtypeId);
 SELECT @CourtId AS CourtId;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.ListClubs @SubtypeId int=NULL,@Query nvarchar(80)=NULL,@UserId int=NULL AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @Q nvarchar(80)=NULLIF(TRIM(@Query),N'''');
 SELECT c.ClubId,c.Name,c.IsPartner,c.ProDiscountPct,v.VenueId,v.Area,v.Address,v.Latitude,v.Longitude,v.ContactPhoneNumber,v.IsVerified AS ContactVerified,v.ListingStatus,
  (SELECT COUNT(*) FROM dbo.Courts k WHERE k.ClubId=c.ClubId AND k.IsActive=1) AS CourtCount,
  (SELECT MIN(k.BasePrice) FROM dbo.Courts k WHERE k.ClubId=c.ClubId AND k.IsActive=1) AS FromPrice,
  (SELECT STRING_AGG(s.Name,N'', '') FROM (SELECT DISTINCT k.SubtypeId FROM dbo.Courts k WHERE k.ClubId=c.ClubId AND k.IsActive=1) d JOIN dbo.Subtypes s ON s.SubtypeId=d.SubtypeId) AS Sports,
  CAST(dbo.ClubRoleRank(c.ClubId,@UserId) AS int) AS MyRoleRank
 FROM dbo.Clubs c JOIN dbo.Venues v ON v.VenueId=c.VenueId
 WHERE c.IsActive=1 AND (@SubtypeId IS NULL OR EXISTS(SELECT 1 FROM dbo.Courts k WHERE k.ClubId=c.ClubId AND k.SubtypeId=@SubtypeId AND k.IsActive=1))
  AND (@Q IS NULL OR CHARINDEX(@Q COLLATE Latin1_General_100_CI_AI,c.Name COLLATE Latin1_General_100_CI_AI)>0 OR CHARINDEX(@Q COLLATE Latin1_General_100_CI_AI,v.Area COLLATE Latin1_General_100_CI_AI)>0)
 ORDER BY c.IsPartner DESC,c.Name;
 SELECT c.ClubId,c.Name,ClubRole=s.Role FROM dbo.ClubStaff s JOIN dbo.Clubs c ON c.ClubId=s.ClubId WHERE s.UserId=@UserId
 UNION SELECT c.ClubId,c.Name,''Operator'' FROM dbo.Clubs c WHERE EXISTS(SELECT 1 FROM dbo.PaymentOperators o WHERE o.UserId=@UserId) AND NOT EXISTS(SELECT 1 FROM dbo.ClubStaff s WHERE s.ClubId=c.ClubId AND s.UserId=@UserId);
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.GetCourtSchedule @ClubId int,@Day date,@UserId int=NULL,@CourtId int=NULL,@IncludeClasses bit=1 AS
BEGIN
 SET NOCOUNT ON;
 -- @Day is a Beirut calendar day. Every slot is computed in Beirut time and returned with its UTC start.
 DECLARE @Rank int=dbo.ClubRoleRank(@ClubId,@UserId),@Pro bit=CASE WHEN @UserId IS NULL THEN 0 ELSE dbo.IsPro(@UserId) END;
 DECLARE @ProPct tinyint=(SELECT CASE WHEN IsPartner=1 THEN ProDiscountPct ELSE 0 END FROM dbo.Clubs WHERE ClubId=@ClubId);
 WITH n AS (SELECT TOP(48) ROW_NUMBER() OVER(ORDER BY (SELECT NULL))-1 AS i FROM sys.all_objects),
 slots AS (
  SELECT k.CourtId,k.Name AS Court,k.SubtypeId,k.SlotMinutes,DATEADD(minute,k.OpenHour*60+n.i*k.SlotMinutes,CAST(@Day AS datetime2(0))) AS LocalStart,k.BasePrice,k.PeakPrice,k.PeakStartHour,k.PeakEndHour
  FROM dbo.Courts k CROSS JOIN n WHERE k.ClubId=@ClubId AND k.IsActive=1 AND (@CourtId IS NULL OR k.CourtId=@CourtId) AND k.OpenHour*60+(n.i+1)*k.SlotMinutes<=k.CloseHour*60)
 SELECT s.CourtId,s.Court,s.SubtypeId,s.LocalStart,DATEADD(minute,s.SlotMinutes,s.LocalStart) AS LocalEnd,dbo.FromBeirut(s.LocalStart) AS StartsAtUtc,
  CAST(CASE WHEN DATEPART(hour,s.LocalStart)>=s.PeakStartHour AND DATEPART(hour,s.LocalStart)<s.PeakEndHour THEN 1 ELSE 0 END AS bit) AS IsPeak,
  CASE WHEN DATEPART(hour,s.LocalStart)>=s.PeakStartHour AND DATEPART(hour,s.LocalStart)<s.PeakEndHour THEN s.PeakPrice ELSE s.BasePrice END AS ListPrice,
  CASE WHEN @Pro=1 THEN @ProPct ELSE 0 END AS ProDiscountPct,
  CASE WHEN dbo.FromBeirut(s.LocalStart)<=SYSUTCDATETIME() THEN ''Past''
   WHEN EXISTS(SELECT 1 FROM dbo.CourtBlocks b WHERE b.CourtId=s.CourtId AND b.StartsAt<dbo.FromBeirut(DATEADD(minute,s.SlotMinutes,s.LocalStart)) AND b.EndsAt>dbo.FromBeirut(s.LocalStart)) THEN ''Blocked''
   WHEN EXISTS(SELECT 1 FROM dbo.CourtBookings cb WHERE cb.CourtId=s.CourtId AND cb.Status IN(''Confirmed'',''Completed'',''NoShow'') AND cb.StartsAt<dbo.FromBeirut(DATEADD(minute,s.SlotMinutes,s.LocalStart)) AND cb.EndsAt>dbo.FromBeirut(s.LocalStart))
    THEN CASE WHEN EXISTS(SELECT 1 FROM dbo.CourtBookings cb WHERE cb.CourtId=s.CourtId AND cb.UserId=@UserId AND cb.Status=''Confirmed'' AND cb.StartsAt=dbo.FromBeirut(s.LocalStart)) THEN ''Mine'' ELSE ''Booked'' END
   ELSE ''Free'' END AS SlotStatus,
  -- Staff see who booked and why a slot is blocked; players never see other players'' names.
  CASE WHEN @Rank>=2 THEN (SELECT TOP(1) COALESCE(u.DisplayName,cb.GuestName) FROM dbo.CourtBookings cb LEFT JOIN dbo.Users u ON u.UserId=cb.UserId WHERE cb.CourtId=s.CourtId AND cb.Status IN(''Confirmed'',''Completed'',''NoShow'') AND cb.StartsAt=dbo.FromBeirut(s.LocalStart)) END AS BookedBy,
  CASE WHEN @Rank>=2 THEN (SELECT TOP(1) cb.BookingId FROM dbo.CourtBookings cb WHERE cb.CourtId=s.CourtId AND cb.Status IN(''Confirmed'',''Completed'',''NoShow'') AND cb.StartsAt=dbo.FromBeirut(s.LocalStart))
   ELSE (SELECT TOP(1) cb.BookingId FROM dbo.CourtBookings cb WHERE cb.CourtId=s.CourtId AND cb.UserId=@UserId AND cb.Status=''Confirmed'' AND cb.StartsAt=dbo.FromBeirut(s.LocalStart)) END AS BookingId,
  CASE WHEN @Rank>=2 THEN (SELECT TOP(1) b.BlockId FROM dbo.CourtBlocks b WHERE b.CourtId=s.CourtId AND b.StartsAt<=dbo.FromBeirut(s.LocalStart) AND b.EndsAt>=dbo.FromBeirut(DATEADD(minute,s.SlotMinutes,s.LocalStart))) END AS BlockId,
  CASE WHEN @Rank>=2 THEN (SELECT TOP(1) b.Reason FROM dbo.CourtBlocks b WHERE b.CourtId=s.CourtId AND b.StartsAt<dbo.FromBeirut(DATEADD(minute,s.SlotMinutes,s.LocalStart)) AND b.EndsAt>dbo.FromBeirut(s.LocalStart)) END AS BlockReason
 FROM slots s ORDER BY s.CourtId,s.LocalStart;
 IF @IncludeClasses=1
 SELECT ClassId,Title,s.Name AS Sport,dbo.ToBeirut(StartsAt) AS LocalStart,DurationMinutes,Capacity,Price,CourtId,
  (SELECT COUNT(*) FROM dbo.ClassRegistrations r WHERE r.ClassId=c.ClassId AND r.Status=''Registered'') AS Registered,
  (SELECT Status FROM dbo.ClassRegistrations r WHERE r.ClassId=c.ClassId AND r.UserId=@UserId AND r.Status<>''Cancelled'') AS MyStatus,
  (SELECT DisplayName FROM dbo.Users u WHERE u.UserId=c.CoachUserId) AS Coach
 FROM dbo.Classes c JOIN dbo.Subtypes s ON s.SubtypeId=c.SubtypeId
 WHERE c.ClubId=@ClubId AND c.Status=''Scheduled'' AND dbo.ToBeirut(c.StartsAt)>=CAST(@Day AS datetime2(0)) AND dbo.ToBeirut(c.StartsAt)<DATEADD(day,1,CAST(@Day AS datetime2(0))) ORDER BY c.StartsAt;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.BookCourt @CourtId int,@UserId int,@StartsAtUtc datetime2(0),@Key uniqueidentifier,@RedemptionCode char(10)=NULL,@GuestName nvarchar(80)=NULL AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Club int,@Slot smallint,@Open tinyint,@Close tinyint,@Base decimal(10,2),@Peak decimal(10,2),@PS tinyint,@PE tinyint,@Active bit;
  -- One lock per court serializes competing bookings for the same court.
  SELECT @Club=ClubId,@Slot=SlotMinutes,@Open=OpenHour,@Close=CloseHour,@Base=BasePrice,@Peak=PeakPrice,@PS=PeakStartHour,@PE=PeakEndHour,@Active=IsActive
  FROM dbo.Courts WITH(UPDLOCK,HOLDLOCK) WHERE CourtId=@CourtId;
  IF @Club IS NULL OR @Active=0 THROW 50001,''Court not found.'',1;
  DECLARE @Existing bigint=(SELECT BookingId FROM dbo.CourtBookings WHERE CreatedBy=@UserId AND IdempotencyKey=@Key);
  IF @Existing IS NOT NULL BEGIN COMMIT; SELECT BookingId,Price,ListPrice,Discount,StartsAt,EndsAt,Status FROM dbo.CourtBookings WHERE BookingId=@Existing; RETURN; END;
  DECLARE @Staff bit=CASE WHEN @GuestName IS NOT NULL THEN 1 ELSE 0 END;
  IF @Staff=1 AND dbo.ClubRoleRank(@Club,@UserId)<2 THROW 50003,''Only club staff can book for walk-in guests.'',1;
  DECLARE @Local datetime2(0)=dbo.ToBeirut(@StartsAtUtc),@End datetime2(0)=DATEADD(minute,@Slot,@StartsAtUtc);
  DECLARE @Minute int=DATEPART(hour,@Local)*60+DATEPART(minute,@Local);
  IF @StartsAtUtc<=SYSUTCDATETIME() THROW 50002,''Choose a future time.'',1;
  IF @StartsAtUtc>DATEADD(day,60,SYSUTCDATETIME()) THROW 50002,''Bookings open up to 60 days ahead.'',1;
  IF @Minute<@Open*60 OR @Minute+@Slot>@Close*60 OR (@Minute-@Open*60)%@Slot<>0 OR DATEPART(second,@Local)<>0 THROW 50002,''Choose one of the listed time slots.'',1;
  IF EXISTS(SELECT 1 FROM dbo.CourtBlocks WHERE CourtId=@CourtId AND StartsAt<@End AND EndsAt>@StartsAtUtc) THROW 50004,''The club has blocked this time.'',1;
  IF EXISTS(SELECT 1 FROM dbo.CourtBookings WHERE CourtId=@CourtId AND Status IN(''Confirmed'',''Completed'',''NoShow'') AND StartsAt<@End AND EndsAt>@StartsAtUtc) THROW 50004,''Someone just booked this slot. Pick another time.'',1;
  IF @Staff=0 AND (SELECT COUNT(*) FROM dbo.CourtBookings WHERE UserId=@UserId AND Status=''Confirmed'' AND StartsAt>SYSUTCDATETIME())>=6 THROW 50004,''You can hold up to 6 upcoming court bookings.'',1;
  DECLARE @List decimal(10,2)=CASE WHEN DATEPART(hour,@Local)>=@PS AND DATEPART(hour,@Local)<@PE THEN @Peak ELSE @Base END,@Discount decimal(10,2)=0,@ProUsed bit=0,@Redemption bigint=NULL;
  IF @Staff=0 AND dbo.IsPro(@UserId)=1
  BEGIN
   DECLARE @ProPct tinyint=(SELECT CASE WHEN IsPartner=1 THEN ProDiscountPct ELSE 0 END FROM dbo.Clubs WHERE ClubId=@Club);
   IF @ProPct>0 BEGIN SET @Discount=ROUND(@List*@ProPct/100.0,2); SET @ProUsed=1; END;
  END;
  IF @RedemptionCode IS NOT NULL
  BEGIN
   DECLARE @Pct tinyint,@RClub int;
   SELECT @Redemption=x.RedemptionId,@Pct=r.DiscountPct,@RClub=r.ClubId FROM dbo.RewardRedemptions x WITH(UPDLOCK,HOLDLOCK) JOIN dbo.Rewards r ON r.RewardId=x.RewardId
   WHERE x.Code=@RedemptionCode AND x.UserId=@UserId AND x.Status=''Issued'' AND x.ExpiresAt>SYSUTCDATETIME() AND r.Kind=''CourtDiscount'';
   IF @Redemption IS NULL THROW 50002,''That reward code is not valid, already used, or expired.'',1;
   IF @RClub IS NOT NULL AND @RClub<>@Club THROW 50002,''That reward is for a different club.'',1;
   SET @Discount=@Discount+ROUND((@List-@Discount)*@Pct/100.0,2);
   UPDATE dbo.RewardRedemptions SET Status=''Used'',UsedAt=SYSUTCDATETIME() WHERE RedemptionId=@Redemption;
  END;
  INSERT dbo.CourtBookings(CourtId,UserId,GuestName,StartsAt,EndsAt,ListPrice,Discount,Source,CreatedBy,IdempotencyKey,RedemptionId,ProDiscount)
  VALUES(@CourtId,IIF(@Staff=1,NULL,@UserId),@GuestName,@StartsAtUtc,@End,@List,@Discount,IIF(@Staff=1,''Staff'',''Player''),@UserId,@Key,@Redemption,@ProUsed);
  DECLARE @Id bigint=SCOPE_IDENTITY();
  IF @Staff=0
  BEGIN
   DECLARE @Pts int=CASE WHEN dbo.IsPro(@UserId)=1 THEN 30 ELSE 20 END;
   EXEC dbo.LoyaltyPost @UserId,@Pts,''CourtBooking'',''Booking'',@Id,N''Court booking'';
   INSERT dbo.UserActivityLogs(UserId,SubtypeId,Action) SELECT @UserId,SubtypeId,''CourtBooked'' FROM dbo.Courts WHERE CourtId=@CourtId;
   INSERT dbo.Notifications(UserId,Title,Body) SELECT s.UserId,N''New court booking'',LEFT(N''A player booked ''+k.Name+N'' at ''+FORMAT(@Local,''ddd d MMM HH:mm''),800)
   FROM dbo.ClubStaff s JOIN dbo.Courts k ON k.ClubId=s.ClubId WHERE k.CourtId=@CourtId AND s.Role IN(''Owner'',''Manager'',''Reception'');
  END;
  COMMIT;
  SELECT BookingId,Price,ListPrice,Discount,StartsAt,EndsAt,Status FROM dbo.CourtBookings WHERE BookingId=@Id;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.CancelCourtBooking @BookingId bigint,@UserId int AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Owner int,@Club int,@Start datetime2(0),@Status varchar(10),@Court int;
  SELECT @Owner=b.UserId,@Club=k.ClubId,@Start=b.StartsAt,@Status=b.Status,@Court=b.CourtId FROM dbo.CourtBookings b WITH(UPDLOCK,HOLDLOCK) JOIN dbo.Courts k ON k.CourtId=b.CourtId WHERE b.BookingId=@BookingId;
  IF @Status IS NULL THROW 50001,''Booking not found.'',1;
  DECLARE @IsStaff bit=CASE WHEN dbo.ClubRoleRank(@Club,@UserId)>=2 THEN 1 ELSE 0 END;
  IF @Owner<>@UserId AND @IsStaff=0 THROW 50003,''You can only cancel your own bookings.'',1;
  IF @Status<>''Confirmed'' THROW 50004,''This booking is already closed.'',1;
  -- Players can cancel up to 6 hours before; staff can cancel any time.
  IF @IsStaff=0 AND @Start<DATEADD(hour,6,SYSUTCDATETIME()) THROW 50004,''Bookings can be cancelled up to 6 hours before. Call the club.'',1;
  UPDATE dbo.CourtBookings SET Status=''Cancelled'',CancelledAt=SYSUTCDATETIME() WHERE BookingId=@BookingId;
  DECLARE @Earned int=(SELECT Points FROM dbo.LoyaltyLedger WHERE Reason=''CourtBooking'' AND RefType=''Booking'' AND RefId=@BookingId AND UserId=@Owner);
  IF @Owner IS NOT NULL AND @Earned>0 BEGIN SET @Earned=-@Earned; EXEC dbo.LoyaltyPost @Owner,@Earned,''Reversal'',''Booking'',@BookingId,N''Court booking cancelled''; END;
  -- Codes used on a cancelled booking are given back.
  UPDATE x SET Status=''Issued'',UsedAt=NULL FROM dbo.RewardRedemptions x JOIN dbo.CourtBookings b ON b.RedemptionId=x.RedemptionId WHERE b.BookingId=@BookingId AND x.ExpiresAt>SYSUTCDATETIME();
  IF @Owner IS NOT NULL AND @Owner<>@UserId INSERT dbo.Notifications(UserId,Title,Body) VALUES(@Owner,N''Court booking cancelled by the club'',N''The club cancelled your booking. Contact them in Chat if you have questions.'');
  COMMIT;
  SELECT ''Cancelled'' AS Status;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.ToggleCourtBlock @CourtId int,@ActorId int,@StartsAtUtc datetime2(0),@Reason nvarchar(120)=NULL AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Club int,@Slot smallint;
  SELECT @Club=ClubId,@Slot=SlotMinutes FROM dbo.Courts WITH(UPDLOCK,HOLDLOCK) WHERE CourtId=@CourtId;
  IF @Club IS NULL THROW 50001,''Court not found.'',1;
  IF dbo.ClubRoleRank(@Club,@ActorId)<2 THROW 50003,''Only club staff can block courts.'',1;
  DECLARE @End datetime2(0)=DATEADD(minute,@Slot,@StartsAtUtc),@Block bigint;
  SELECT @Block=BlockId FROM dbo.CourtBlocks WHERE CourtId=@CourtId AND StartsAt=@StartsAtUtc AND EndsAt=@End;
  IF @Block IS NOT NULL
  BEGIN
   DELETE dbo.CourtBlocks WHERE BlockId=@Block;
   COMMIT; SELECT ''Unblocked'' AS Status; RETURN;
  END;
  IF EXISTS(SELECT 1 FROM dbo.CourtBookings WHERE CourtId=@CourtId AND Status=''Confirmed'' AND StartsAt<@End AND EndsAt>@StartsAtUtc) THROW 50004,''This slot is booked. Cancel the booking first.'',1;
  INSERT dbo.CourtBlocks(CourtId,StartsAt,EndsAt,Reason,CreatedBy) VALUES(@CourtId,@StartsAtUtc,@End,COALESCE(NULLIF(TRIM(@Reason),N''''),N''Blocked by club''),@ActorId);
  COMMIT;
  SELECT ''Blocked'' AS Status;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.CreateClassSeries @ClubId int,@ActorId int,@Title nvarchar(120),@SubtypeId int,@CourtId int=NULL,@CoachUserId int=NULL,
 @FirstStartsAtUtc datetime2(0),@DurationMinutes smallint,@Capacity smallint,@Price decimal(10,2),@Weeks tinyint=1 AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @Rank int=dbo.ClubRoleRank(@ClubId,@ActorId);
 IF @Rank<3 AND NOT(@Rank=1 AND @CoachUserId=@ActorId) THROW 50003,''Managers, owners or the coach can schedule classes.'',1;
 IF NULLIF(TRIM(@Title),N'''') IS NULL OR @Weeks NOT BETWEEN 1 AND 26 OR @FirstStartsAtUtc<=SYSUTCDATETIME() THROW 50002,''Check the title, first date and number of weeks (1-26).'',1;
 IF @CourtId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.Courts WHERE CourtId=@CourtId AND ClubId=@ClubId) THROW 50002,''Choose a court of this club.'',1;
 IF @CoachUserId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.ClubStaff WHERE ClubId=@ClubId AND UserId=@CoachUserId) THROW 50002,''The coach must be on the club staff.'',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Series uniqueidentifier=NEWID(),@i int=0,@Local datetime2(0)=dbo.ToBeirut(@FirstStartsAtUtc),@S datetime2(0);
  WHILE @i<@Weeks
  BEGIN
   -- Weekly at the same Beirut wall-clock time (correct across daylight-saving changes).
   SET @S=dbo.FromBeirut(DATEADD(week,@i,@Local));
   INSERT dbo.Classes(ClubId,CourtId,CoachUserId,Title,SubtypeId,StartsAt,DurationMinutes,Capacity,Price,SeriesId,CreatedBy)
   VALUES(@ClubId,@CourtId,@CoachUserId,TRIM(@Title),@SubtypeId,@S,@DurationMinutes,@Capacity,@Price,@Series,@ActorId);
   -- A class on a court reserves that court.
   IF @CourtId IS NOT NULL
   BEGIN
    IF EXISTS(SELECT 1 FROM dbo.CourtBookings WHERE CourtId=@CourtId AND Status=''Confirmed'' AND StartsAt<DATEADD(minute,@DurationMinutes,@S) AND EndsAt>@S)
     THROW 50004,''A player booking overlaps one of these class times.'',1;
    INSERT dbo.CourtBlocks(CourtId,StartsAt,EndsAt,Reason,CreatedBy) VALUES(@CourtId,@S,DATEADD(minute,@DurationMinutes,@S),N''Class: ''+TRIM(@Title),@ActorId);
   END;
   SET @i+=1;
  END;
  COMMIT;
  SELECT @Series AS SeriesId,@Weeks AS Created;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.RegisterForClass @ClassId int,@UserId int,@Cancel bit=0 AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Cap smallint,@Start datetime2(0),@Status varchar(10);
  SELECT @Cap=Capacity,@Start=StartsAt,@Status=Status FROM dbo.Classes WITH(UPDLOCK,HOLDLOCK) WHERE ClassId=@ClassId;
  IF @Cap IS NULL THROW 50001,''Class not found.'',1;
  IF @Status<>''Scheduled'' OR @Start<=SYSUTCDATETIME() THROW 50002,''This class is no longer open.'',1;
  IF @Cancel=1
  BEGIN
   UPDATE dbo.ClassRegistrations SET Status=''Cancelled'' WHERE ClassId=@ClassId AND UserId=@UserId AND Status<>''Cancelled'';
   IF @@ROWCOUNT=1
   BEGIN
    EXEC dbo.LoyaltyPost @UserId,-15,''Reversal'',''Class'',@ClassId,N''Class cancelled'';
    -- First waitlisted player takes the place.
    DECLARE @Next int=(SELECT TOP(1) UserId FROM dbo.ClassRegistrations WHERE ClassId=@ClassId AND Status=''Waitlisted'' ORDER BY CreatedAt);
    IF @Next IS NOT NULL
    BEGIN
     UPDATE dbo.ClassRegistrations SET Status=''Registered'' WHERE ClassId=@ClassId AND UserId=@Next;
     EXEC dbo.LoyaltyPost @Next,15,''Class'',''Class'',@ClassId,N''Class registration'';
     INSERT dbo.Notifications(UserId,Title,Body) VALUES(@Next,N''You''''re in the class'',N''A place opened and you moved from the waitlist.'');
    END;
   END;
   COMMIT; SELECT ''Cancelled'' AS Status; RETURN;
  END;
  DECLARE @Mine varchar(10)=(SELECT Status FROM dbo.ClassRegistrations WHERE ClassId=@ClassId AND UserId=@UserId);
  IF @Mine IN(''Registered'',''Waitlisted'') BEGIN COMMIT; SELECT @Mine AS Status; RETURN; END;
  DECLARE @New varchar(10)=CASE WHEN (SELECT COUNT(*) FROM dbo.ClassRegistrations WHERE ClassId=@ClassId AND Status=''Registered'')<@Cap THEN ''Registered'' ELSE ''Waitlisted'' END;
  MERGE dbo.ClassRegistrations AS t USING (SELECT @ClassId c,@UserId u) s ON t.ClassId=s.c AND t.UserId=s.u
  WHEN MATCHED THEN UPDATE SET Status=@New,CreatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(ClassId,UserId,Status) VALUES(@ClassId,@UserId,@New);
  IF @New=''Registered''
  BEGIN
   -- Points for a class are earned once; re-registering after a cancellation does not earn again.
   EXEC dbo.LoyaltyPost @UserId,15,''Class'',''Class'',@ClassId,N''Class registration'';
   INSERT dbo.UserActivityLogs(UserId,SubtypeId,Action) SELECT @UserId,SubtypeId,''ClassJoined'' FROM dbo.Classes WHERE ClassId=@ClassId;
  END;
  COMMIT;
  SELECT @New AS Status;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.GetClubDashboard @ClubId int,@ActorId int,@Days int=30 AS
BEGIN
 SET NOCOUNT ON;
 IF dbo.ClubRoleRank(@ClubId,@ActorId)<3 THROW 50003,''Managers and owners can see the dashboard.'',1;
 IF @Days NOT BETWEEN 1 AND 365 SET @Days=30;
 DECLARE @From datetime2(0)=DATEADD(day,-@Days,SYSUTCDATETIME()),@Now datetime2(0)=SYSUTCDATETIME();
 -- Revenue = court bookings that have taken place (not cancelled) + class registrations, at the price the player owes the club.
 DECLARE @Court decimal(14,2)=(SELECT COALESCE(SUM(b.Price),0) FROM dbo.CourtBookings b JOIN dbo.Courts k ON k.CourtId=b.CourtId WHERE k.ClubId=@ClubId AND b.Status IN(''Confirmed'',''Completed'') AND b.StartsAt>=@From AND b.StartsAt<@Now);
 DECLARE @Class decimal(14,2)=(SELECT COALESCE(SUM(c.Price),0) FROM dbo.ClassRegistrations r JOIN dbo.Classes c ON c.ClassId=r.ClassId WHERE c.ClubId=@ClubId AND r.Status=''Registered'' AND c.Status=''Scheduled'' AND c.StartsAt>=@From AND c.StartsAt<@Now);
 DECLARE @Exp decimal(14,2)=(SELECT COALESCE(SUM(Amount),0) FROM dbo.ClubExpenses WHERE ClubId=@ClubId AND SpentOn>=CAST(@From AS date));
 DECLARE @SlotsTotal decimal(14,2)=(SELECT COALESCE(SUM(CAST((CloseHour-OpenHour)*60/SlotMinutes AS decimal(14,2))),0)*@Days FROM dbo.Courts WHERE ClubId=@ClubId AND IsActive=1);
 DECLARE @SlotsUsed decimal(14,2)=(SELECT COUNT(*) FROM dbo.CourtBookings b JOIN dbo.Courts k ON k.CourtId=b.CourtId WHERE k.ClubId=@ClubId AND b.Status IN(''Confirmed'',''Completed'') AND b.StartsAt>=@From AND b.StartsAt<@Now);
 SELECT @Court AS CourtRevenue,@Class AS ClassRevenue,@Court+@Class AS Revenue,@Exp AS Expenses,@Court+@Class-@Exp AS NetProfit,
  CAST(CASE WHEN @SlotsTotal=0 THEN 0 ELSE 100*@SlotsUsed/@SlotsTotal END AS decimal(5,1)) AS OccupancyPct,
  (SELECT COUNT(*) FROM dbo.CourtBookings b JOIN dbo.Courts k ON k.CourtId=b.CourtId WHERE k.ClubId=@ClubId AND b.Status=''Confirmed'' AND b.StartsAt>=@Now) AS UpcomingBookings,
  (SELECT COUNT(*) FROM dbo.CourtBookings b JOIN dbo.Courts k ON k.CourtId=b.CourtId WHERE k.ClubId=@ClubId AND b.Status=''Cancelled'' AND b.StartsAt>=@From) AS Cancellations,
  @Days AS Days;
 SELECT CAST(dbo.ToBeirut(b.StartsAt) AS date) AS Day,SUM(b.Price) AS Revenue,COUNT(*) AS Bookings
 FROM dbo.CourtBookings b JOIN dbo.Courts k ON k.CourtId=b.CourtId WHERE k.ClubId=@ClubId AND b.Status IN(''Confirmed'',''Completed'') AND b.StartsAt>=@From AND b.StartsAt<@Now
 GROUP BY CAST(dbo.ToBeirut(b.StartsAt) AS date) ORDER BY Day;
 SELECT DATEPART(hour,dbo.ToBeirut(b.StartsAt)) AS Hour,COUNT(*) AS Bookings FROM dbo.CourtBookings b JOIN dbo.Courts k ON k.CourtId=b.CourtId
 WHERE k.ClubId=@ClubId AND b.Status IN(''Confirmed'',''Completed'') AND b.StartsAt>=@From GROUP BY DATEPART(hour,dbo.ToBeirut(b.StartsAt)) ORDER BY Hour;
 SELECT Category,SUM(Amount) AS Amount FROM dbo.ClubExpenses WHERE ClubId=@ClubId AND SpentOn>=CAST(@From AS date) GROUP BY Category ORDER BY Amount DESC;
 SELECT k.CourtId,k.Name,k.SubtypeId,k.SlotMinutes,k.OpenHour,k.CloseHour,k.BasePrice,k.PeakPrice,k.PeakStartHour,k.PeakEndHour,k.IsActive FROM dbo.Courts k WHERE k.ClubId=@ClubId ORDER BY k.Name;
 SELECT s.UserId,u.DisplayName,u.Email,s.Role FROM dbo.ClubStaff s JOIN dbo.Users u ON u.UserId=s.UserId WHERE s.ClubId=@ClubId AND dbo.ClubRoleRank(@ClubId,@ActorId)>=4 ORDER BY s.Role,u.DisplayName;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.AddClubExpense @ClubId int,@ActorId int,@Amount decimal(12,2),@Category varchar(16),@SpentOn date,@Note nvarchar(200)=NULL AS
BEGIN
 SET NOCOUNT ON;
 IF dbo.ClubRoleRank(@ClubId,@ActorId)<4 THROW 50003,''Only the club owner records expenses.'',1;
 IF @Amount<=0 OR @SpentOn>CAST(SYSUTCDATETIME() AS date) THROW 50002,''Enter a positive amount and a date that is not in the future.'',1;
 INSERT dbo.ClubExpenses(ClubId,Amount,Category,SpentOn,Note,CreatedBy) VALUES(@ClubId,@Amount,@Category,@SpentOn,@Note,@ActorId);
 SELECT SCOPE_IDENTITY() AS ExpenseId;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.MyCourtBookings @UserId int AS
BEGIN
 SET NOCOUNT ON;
 SELECT TOP(50) b.BookingId,b.CourtId,k.Name AS Court,c.ClubId,c.Name AS Club,v.Area,b.StartsAt,dbo.ToBeirut(b.StartsAt) AS LocalStart,b.EndsAt,b.ListPrice,b.Discount,b.Price,b.Status,b.ProDiscount,
  CAST(CASE WHEN b.Status=''Confirmed'' AND b.StartsAt>=DATEADD(hour,6,SYSUTCDATETIME()) THEN 1 ELSE 0 END AS bit) AS CanCancel
 FROM dbo.CourtBookings b JOIN dbo.Courts k ON k.CourtId=b.CourtId JOIN dbo.Clubs c ON c.ClubId=k.ClubId JOIN dbo.Venues v ON v.VenueId=c.VenueId
 WHERE b.UserId=@UserId ORDER BY CASE WHEN b.StartsAt>=SYSUTCDATETIME() THEN 0 ELSE 1 END,ABS(DATEDIFF(minute,SYSUTCDATETIME(),b.StartsAt));
 SELECT TOP(30) c.ClassId,c.Title,cl.Name AS Club,dbo.ToBeirut(c.StartsAt) AS LocalStart,c.Price,r.Status FROM dbo.ClassRegistrations r JOIN dbo.Classes c ON c.ClassId=r.ClassId JOIN dbo.Clubs cl ON cl.ClubId=c.ClubId
 WHERE r.UserId=@UserId AND r.Status<>''Cancelled'' AND c.StartsAt>=DATEADD(day,-7,SYSUTCDATETIME()) ORDER BY c.StartsAt;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.SaveCoachProfile @UserId int,@Headline nvarchar(120),@Bio nvarchar(800),@HourlyRate decimal(10,2)=NULL,@Area nvarchar(80)=NULL,@SportsJson nvarchar(400),@IsListed bit=1 AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF NULLIF(TRIM(@Headline),N'''') IS NULL OR ISJSON(@SportsJson)<>1 OR (SELECT COUNT(*) FROM OPENJSON(@SportsJson)) NOT BETWEEN 1 AND 5 THROW 50002,''Add a headline and 1-5 sports you coach.'',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  MERGE dbo.CoachProfiles AS t USING (SELECT @UserId u) s ON t.UserId=s.u
  WHEN MATCHED THEN UPDATE SET Headline=TRIM(@Headline),Bio=COALESCE(@Bio,N''''),HourlyRate=@HourlyRate,Area=@Area,IsListed=@IsListed,UpdatedAt=SYSUTCDATETIME()
  WHEN NOT MATCHED THEN INSERT(UserId,Headline,Bio,HourlyRate,Area,IsListed) VALUES(@UserId,TRIM(@Headline),COALESCE(@Bio,N''''),@HourlyRate,@Area,@IsListed);
  DELETE dbo.CoachSports WHERE UserId=@UserId;
  INSERT dbo.CoachSports(UserId,SubtypeId) SELECT DISTINCT @UserId,s.SubtypeId FROM OPENJSON(@SportsJson) j JOIN dbo.Subtypes s ON s.SubtypeId=TRY_CONVERT(int,j.value);
  COMMIT;
  SELECT ''Saved'' AS Status;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.ListCoaches @SubtypeId int=NULL,@Area nvarchar(80)=NULL,@UserId int=NULL AS
BEGIN
 SET NOCOUNT ON;
 SELECT TOP(60) p.UserId,u.DisplayName,p.Headline,p.Bio,p.HourlyRate,p.Area,CAST(dbo.IsPro(p.UserId) AS bit) AS IsPro,
  (SELECT STRING_AGG(s.Name,N'', '') FROM dbo.CoachSports cs JOIN dbo.Subtypes s ON s.SubtypeId=cs.SubtypeId WHERE cs.UserId=p.UserId) AS Sports,
  (SELECT STRING_AGG(c.Name,N'', '') FROM dbo.ClubStaff st JOIN dbo.Clubs c ON c.ClubId=st.ClubId WHERE st.UserId=p.UserId AND st.Role=''Coach'') AS Clubs,
  (SELECT COUNT(*) FROM dbo.Classes c WHERE c.CoachUserId=p.UserId AND c.Status=''Scheduled'' AND c.StartsAt>SYSUTCDATETIME()) AS UpcomingClasses
 FROM dbo.CoachProfiles p JOIN dbo.Users u ON u.UserId=p.UserId
 WHERE p.IsListed=1 AND (@SubtypeId IS NULL OR EXISTS(SELECT 1 FROM dbo.CoachSports cs WHERE cs.UserId=p.UserId AND cs.SubtypeId=@SubtypeId))
  AND (NULLIF(TRIM(@Area),N'''') IS NULL OR CHARINDEX(TRIM(@Area) COLLATE Latin1_General_100_CI_AI,COALESCE(p.Area,N'''') COLLATE Latin1_General_100_CI_AI)>0)
 ORDER BY CASE WHEN EXISTS(SELECT 1 FROM dbo.ClubStaff st WHERE st.UserId=p.UserId AND st.Role=''Coach'') THEN 0 ELSE 1 END,u.DisplayName;
 SELECT p.Headline,p.Bio,p.HourlyRate,p.Area,p.IsListed,(SELECT ''[''+STRING_AGG(CONVERT(varchar(12),SubtypeId),'','')+'']'' FROM dbo.CoachSports WHERE UserId=p.UserId) AS SportsJson
 FROM dbo.CoachProfiles p WHERE p.UserId=@UserId;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.FriendRequest @UserId int,@Email nvarchar(254)=NULL,@OtherId int=NULL,@Action varchar(8) AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 -- Friends are added by exact email (no public user search) to protect privacy.
 IF @OtherId IS NULL SET @OtherId=(SELECT UserId FROM dbo.Users WHERE Email=LOWER(TRIM(@Email)) AND PasswordHash<>''DISABLED_FIXTURE'');
 IF @OtherId IS NULL THROW 50001,''No GameOn player with that email. Ask them to sign up first.'',1;
 IF @OtherId=@UserId THROW 50002,''That is you.'',1;
 DECLARE @L int=IIF(@UserId<@OtherId,@UserId,@OtherId),@H int=IIF(@UserId<@OtherId,@OtherId,@UserId);
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Status varchar(10),@By int;
  SELECT @Status=Status,@By=RequestedBy FROM dbo.Friendships WITH(UPDLOCK,HOLDLOCK) WHERE UserLow=@L AND UserHigh=@H;
  IF @Action=''Request''
  BEGIN
   IF @Status=''Accepted'' THROW 50004,''You are already friends.'',1;
   IF @Status=''Pending'' AND @By<>@UserId
    UPDATE dbo.Friendships SET Status=''Accepted'',AcceptedAt=SYSUTCDATETIME() WHERE UserLow=@L AND UserHigh=@H; -- both asked: accept
   ELSE IF @Status IS NULL
   BEGIN
    INSERT dbo.Friendships(UserLow,UserHigh,RequestedBy) VALUES(@L,@H,@UserId);
    INSERT dbo.Notifications(UserId,Title,Body) SELECT @OtherId,N''New friend request'',DisplayName+N'' wants to play with you. Open Chat > Friends.'' FROM dbo.Users WHERE UserId=@UserId;
   END;
  END
  ELSE IF @Action=''Accept''
  BEGIN
   IF @Status<>''Pending'' OR @By=@UserId THROW 50004,''No request to accept.'',1;
   UPDATE dbo.Friendships SET Status=''Accepted'',AcceptedAt=SYSUTCDATETIME() WHERE UserLow=@L AND UserHigh=@H;
  END
  ELSE IF @Action=''Remove'' DELETE dbo.Friendships WHERE UserLow=@L AND UserHigh=@H;
  ELSE THROW 50002,''Unknown action.'',1;
  COMMIT;
  SELECT COALESCE((SELECT Status FROM dbo.Friendships WHERE UserLow=@L AND UserHigh=@H),''None'') AS Status,@OtherId AS UserId;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.ListFriends @UserId int AS
BEGIN
 SET NOCOUNT ON;
 SELECT o.UserId,o.DisplayName,f.Status,CAST(CASE WHEN f.RequestedBy=@UserId THEN 1 ELSE 0 END AS bit) AS RequestedByMe,CAST(dbo.IsPro(o.UserId) AS bit) AS IsPro
 FROM dbo.Friendships f JOIN dbo.Users o ON o.UserId=IIF(f.UserLow=@UserId,f.UserHigh,f.UserLow)
 WHERE @UserId IN(f.UserLow,f.UserHigh) ORDER BY f.Status DESC,o.DisplayName;
END;');
 EXEC(N'CREATE OR ALTER FUNCTION dbo.CanUseConversation(@ConversationId bigint,@UserId int) RETURNS bit AS
BEGIN
 DECLARE @Kind varchar(8),@Game int,@Club int,@L int,@H int;
 SELECT @Kind=Kind,@Game=GameId,@Club=ClubId,@L=UserLow,@H=UserHigh FROM dbo.Conversations WHERE ConversationId=@ConversationId;
 IF @Kind=''Direct'' RETURN CASE WHEN @UserId IN(@L,@H) AND EXISTS(SELECT 1 FROM dbo.Friendships WHERE UserLow=@L AND UserHigh=@H AND Status=''Accepted'') THEN 1 ELSE 0 END;
 IF @Kind=''Game'' RETURN CASE WHEN EXISTS(SELECT 1 FROM dbo.GamesAndEvents WHERE EventId=@Game AND HostUserId=@UserId)
  OR EXISTS(SELECT 1 FROM dbo.Participations WHERE GameId=@Game AND UserId=@UserId)
  OR EXISTS(SELECT 1 FROM dbo.GameJoinRequests WHERE GameId=@Game AND UserId=@UserId AND Status=''Approved'') THEN 1 ELSE 0 END;
 IF @Kind=''Club'' RETURN CASE WHEN @UserId=@L OR dbo.ClubRoleRank(@Club,@UserId)>=2 THEN 1 ELSE 0 END;
 RETURN 0;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.OpenConversation @UserId int,@Kind varchar(8),@GameId int=NULL,@ClubId int=NULL,@OtherUserId int=NULL AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @Id bigint,@L int,@H int;
 BEGIN TRY
  BEGIN TRANSACTION;
  IF @Kind=''Game''
  BEGIN
   SELECT @Id=ConversationId FROM dbo.Conversations WITH(UPDLOCK,HOLDLOCK) WHERE Kind=''Game'' AND GameId=@GameId;
   IF @Id IS NULL AND EXISTS(SELECT 1 FROM dbo.GamesAndEvents WHERE EventId=@GameId) BEGIN INSERT dbo.Conversations(Kind,GameId) VALUES(''Game'',@GameId); SET @Id=SCOPE_IDENTITY(); END;
  END
  ELSE IF @Kind=''Direct''
  BEGIN
   SELECT @L=IIF(@UserId<@OtherUserId,@UserId,@OtherUserId),@H=IIF(@UserId<@OtherUserId,@OtherUserId,@UserId);
   SELECT @Id=ConversationId FROM dbo.Conversations WITH(UPDLOCK,HOLDLOCK) WHERE Kind=''Direct'' AND UserLow=@L AND UserHigh=@H;
   IF @Id IS NULL AND EXISTS(SELECT 1 FROM dbo.Friendships WHERE UserLow=@L AND UserHigh=@H AND Status=''Accepted'') BEGIN INSERT dbo.Conversations(Kind,UserLow,UserHigh) VALUES(''Direct'',@L,@H); SET @Id=SCOPE_IDENTITY(); END;
  END
  ELSE IF @Kind=''Club''
  BEGIN
   -- A player opens a thread with a club''s reception; staff open an existing thread by id.
   SELECT @Id=ConversationId FROM dbo.Conversations WITH(UPDLOCK,HOLDLOCK) WHERE Kind=''Club'' AND ClubId=@ClubId AND UserLow=@UserId;
   IF @Id IS NULL AND EXISTS(SELECT 1 FROM dbo.Clubs WHERE ClubId=@ClubId AND IsActive=1) BEGIN INSERT dbo.Conversations(Kind,ClubId,UserLow) VALUES(''Club'',@ClubId,@UserId); SET @Id=SCOPE_IDENTITY(); END;
  END;
  IF @Id IS NULL OR dbo.CanUseConversation(@Id,@UserId)=0 THROW 50003,''You cannot open this chat.'',1;
  COMMIT;
  SELECT @Id AS ConversationId;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.SendMessage @ConversationId bigint,@UserId int,@Body nvarchar(1000),@ClientKey uniqueidentifier AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 SET @Body=TRIM(@Body);
 IF @Body IS NULL OR LEN(@Body) NOT BETWEEN 1 AND 1000 THROW 50002,''Write a message (up to 1000 characters).'',1;
 IF dbo.CanUseConversation(@ConversationId,@UserId)=0 THROW 50003,''You are not part of this chat.'',1;
 -- Simple flood control: 20 messages per minute per sender.
 IF (SELECT COUNT(*) FROM dbo.Messages WHERE SenderId=@UserId AND CreatedAt>DATEADD(minute,-1,SYSUTCDATETIME()))>=20 THROW 50004,''You are sending messages too fast. Wait a moment.'',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Id bigint=(SELECT MessageId FROM dbo.Messages WHERE SenderId=@UserId AND ClientKey=@ClientKey);
  IF @Id IS NULL
  BEGIN
   INSERT dbo.Messages(ConversationId,SenderId,Body,ClientKey) VALUES(@ConversationId,@UserId,@Body,@ClientKey);
   SET @Id=SCOPE_IDENTITY();
   UPDATE dbo.Conversations SET LastMessageAt=SYSUTCDATETIME() WHERE ConversationId=@ConversationId;
   MERGE dbo.ConversationReads AS t USING (SELECT @ConversationId c,@UserId u) s ON t.ConversationId=s.c AND t.UserId=s.u
   WHEN MATCHED THEN UPDATE SET LastReadMessageId=@Id WHEN NOT MATCHED THEN INSERT(ConversationId,UserId,LastReadMessageId) VALUES(@ConversationId,@UserId,@Id);
  END;
  COMMIT;
  SELECT m.MessageId,m.ConversationId,m.SenderId,u.DisplayName AS SenderName,m.Body,m.CreatedAt FROM dbo.Messages m JOIN dbo.Users u ON u.UserId=m.SenderId WHERE m.MessageId=@Id;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.GetMessages @ConversationId bigint,@UserId int,@BeforeId bigint=NULL AS
BEGIN
 SET NOCOUNT ON;
 IF dbo.CanUseConversation(@ConversationId,@UserId)=0 THROW 50003,''You are not part of this chat.'',1;
 SELECT TOP(50) m.MessageId,m.ConversationId,m.SenderId,u.DisplayName AS SenderName,m.Body,m.CreatedAt FROM dbo.Messages m JOIN dbo.Users u ON u.UserId=m.SenderId
 WHERE m.ConversationId=@ConversationId AND (@BeforeId IS NULL OR m.MessageId<@BeforeId) ORDER BY m.MessageId DESC;
 DECLARE @Last bigint=(SELECT MAX(MessageId) FROM dbo.Messages WHERE ConversationId=@ConversationId);
 IF @Last IS NOT NULL AND @BeforeId IS NULL
  MERGE dbo.ConversationReads AS t USING (SELECT @ConversationId c,@UserId u) s ON t.ConversationId=s.c AND t.UserId=s.u
  WHEN MATCHED THEN UPDATE SET LastReadMessageId=@Last WHEN NOT MATCHED THEN INSERT(ConversationId,UserId,LastReadMessageId) VALUES(@ConversationId,@UserId,@Last);
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.ListConversations @UserId int AS
BEGIN
 SET NOCOUNT ON;
 -- Game chats for games the user is in, direct chats with friends, and club threads (as player or staff).
 SELECT TOP(100) c.ConversationId,c.Kind,c.GameId,c.ClubId,c.LastMessageAt,
  CASE c.Kind WHEN ''Game'' THEN s.Name+N''  -  ''+FORMAT(dbo.ToBeirut(g.StartsAt),''ddd d MMM HH:mm'') WHEN ''Club'' THEN CASE WHEN c.UserLow=@UserId THEN cl.Name ELSE cl.Name+N''  -  ''+pu.DisplayName END
   ELSE (SELECT DisplayName FROM dbo.Users WHERE UserId=IIF(c.UserLow=@UserId,c.UserHigh,c.UserLow)) END AS Title,
  (SELECT TOP(1) LEFT(m.Body,80) FROM dbo.Messages m WHERE m.ConversationId=c.ConversationId ORDER BY m.MessageId DESC) AS LastMessage,
  (SELECT COUNT(*) FROM dbo.Messages m WHERE m.ConversationId=c.ConversationId AND m.SenderId<>@UserId
    AND m.MessageId>COALESCE((SELECT r.LastReadMessageId FROM dbo.ConversationReads r WHERE r.ConversationId=c.ConversationId AND r.UserId=@UserId),0)) AS Unread
 FROM dbo.Conversations c LEFT JOIN dbo.GamesAndEvents g ON g.EventId=c.GameId LEFT JOIN dbo.Subtypes s ON s.SubtypeId=g.SubtypeId
  LEFT JOIN dbo.Clubs cl ON cl.ClubId=c.ClubId LEFT JOIN dbo.Users pu ON pu.UserId=c.UserLow AND c.Kind=''Club''
 WHERE dbo.CanUseConversation(c.ConversationId,@UserId)=1 AND (c.LastMessageAt IS NOT NULL OR c.Kind<>''Club'' OR c.UserLow=@UserId)
 ORDER BY COALESCE(c.LastMessageAt,c.CreatedAt) DESC;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.ConversationMembers @ConversationId bigint AS
BEGIN
 SET NOCOUNT ON;
 -- Users to push real-time events to (used by the API after a message is stored).
 DECLARE @Kind varchar(8),@Game int,@Club int,@L int,@H int;
 SELECT @Kind=Kind,@Game=GameId,@Club=ClubId,@L=UserLow,@H=UserHigh FROM dbo.Conversations WHERE ConversationId=@ConversationId;
 IF @Kind=''Direct'' SELECT UserId FROM dbo.Users WHERE UserId IN(@L,@H);
 ELSE IF @Kind=''Game'' SELECT HostUserId AS UserId FROM dbo.GamesAndEvents WHERE EventId=@Game UNION SELECT UserId FROM dbo.Participations WHERE GameId=@Game UNION SELECT UserId FROM dbo.GameJoinRequests WHERE GameId=@Game AND Status=''Approved'';
 ELSE IF @Kind=''Club'' SELECT @L AS UserId UNION SELECT UserId FROM dbo.ClubStaff WHERE ClubId=@Club AND Role IN(''Owner'',''Manager'',''Reception'');
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.GetRewards @UserId int AS
BEGIN
 SET NOCOUNT ON;
 SELECT COALESCE(a.Points,0) AS Points,COALESCE(a.LifetimePoints,0) AS LifetimePoints,CAST(dbo.IsPro(@UserId) AS bit) AS IsPro,
  (SELECT MAX(EndsAt) FROM dbo.Memberships WHERE UserId=@UserId AND Tier=''Pro'') AS ProUntil
 FROM (SELECT @UserId AS UserId) x LEFT JOIN dbo.LoyaltyAccounts a ON a.UserId=x.UserId;
 SELECT r.RewardId,r.Title,r.Description,r.PointsCost,r.Kind,r.DiscountPct,c.Name AS Club,r.Stock FROM dbo.Rewards r LEFT JOIN dbo.Clubs c ON c.ClubId=r.ClubId
 WHERE r.IsActive=1 AND (r.Stock IS NULL OR r.Stock>0) ORDER BY r.PointsCost;
 SELECT TOP(30) EntryId,Points,BalanceAfter,Reason,Note,CreatedAt FROM dbo.LoyaltyLedger WHERE UserId=@UserId ORDER BY EntryId DESC;
 SELECT TOP(30) x.RedemptionId,x.Code,x.Status,x.ExpiresAt,x.CreatedAt,r.Title FROM dbo.RewardRedemptions x JOIN dbo.Rewards r ON r.RewardId=x.RewardId WHERE x.UserId=@UserId ORDER BY x.RedemptionId DESC;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.RedeemReward @UserId int,@RewardId int,@Key uniqueidentifier AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Existing bigint=(SELECT RedemptionId FROM dbo.RewardRedemptions WHERE UserId=@UserId AND IdempotencyKey=@Key);
  IF @Existing IS NULL
  BEGIN
   DECLARE @Cost int,@Stock int;
   SELECT @Cost=PointsCost,@Stock=Stock FROM dbo.Rewards WITH(UPDLOCK,HOLDLOCK) WHERE RewardId=@RewardId AND IsActive=1;
   IF @Cost IS NULL THROW 50001,''Reward not available.'',1;
   IF @Stock IS NOT NULL AND @Stock<1 THROW 50004,''This reward is out of stock.'',1;
   IF COALESCE((SELECT Points FROM dbo.LoyaltyAccounts WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@UserId),0)<@Cost THROW 50006,''Not enough points yet. Keep playing!'',1;
   INSERT dbo.RewardRedemptions(RewardId,UserId,Code,PointsSpent,IdempotencyKey,ExpiresAt)
   VALUES(@RewardId,@UserId,UPPER(LEFT(REPLACE(CONVERT(varchar(36),NEWID()),''-'',''''),10)),@Cost,@Key,DATEADD(day,90,SYSUTCDATETIME()));
   SET @Existing=SCOPE_IDENTITY();
   DECLARE @Neg int=-@Cost;
   EXEC dbo.LoyaltyPost @UserId,@Neg,''Redemption'',''Redemption'',@Existing,N''Reward redeemed'';
   IF @Stock IS NOT NULL UPDATE dbo.Rewards SET Stock=Stock-1 WHERE RewardId=@RewardId;
  END;
  COMMIT;
  SELECT x.RedemptionId,x.Code,x.ExpiresAt,r.Title FROM dbo.RewardRedemptions x JOIN dbo.Rewards r ON r.RewardId=x.RewardId WHERE x.RedemptionId=@Existing;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.BuyPro @UserId int,@Key uniqueidentifier,@Price decimal(10,2),@Days int AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @Price<=0 OR @Days NOT BETWEEN 1 AND 366 THROW 50002,''Invalid Pro plan.'',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @Id bigint=(SELECT MembershipId FROM dbo.Memberships WHERE UserId=@UserId AND IdempotencyKey=@Key);
  IF @Id IS NULL
  BEGIN
   -- Renewals extend from the current end date, never overlapping.
   DECLARE @Start datetime2(3)=(SELECT MAX(EndsAt) FROM dbo.Memberships WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@UserId AND EndsAt>SYSUTCDATETIME());
   SET @Start=COALESCE(@Start,SYSUTCDATETIME());
   INSERT dbo.Memberships(UserId,Tier,StartsAt,EndsAt,PricePaid,IdempotencyKey) VALUES(@UserId,''Pro'',@Start,DATEADD(day,@Days,@Start),@Price,@Key);
   SET @Id=SCOPE_IDENTITY();
   DECLARE @Neg decimal(12,2)=-@Price;
   IF NOT EXISTS(SELECT 1 FROM dbo.WalletAccounts WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@UserId) INSERT dbo.WalletAccounts(UserId) VALUES(@UserId);
   DECLARE @Bal decimal(12,2)=(SELECT Balance FROM dbo.WalletAccounts WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@UserId);
   IF @Bal<@Price THROW 50006,''Not enough money in your GameOn wallet. Top up first.'',1;
   UPDATE dbo.WalletAccounts SET Balance=Balance-@Price,UpdatedAt=SYSUTCDATETIME() WHERE UserId=@UserId;
   INSERT dbo.WalletLedger(UserId,Amount,BalanceAfter,Kind,MembershipId,Note) VALUES(@UserId,@Neg,@Bal-@Price,''Membership'',@Id,N''GameOn Pro'');
   EXEC dbo.LoyaltyPost @UserId,100,''ProBonus'',''Membership'',@Id,N''Welcome to GameOn Pro'';
  END;
  COMMIT;
  SELECT MembershipId,StartsAt,EndsAt FROM dbo.Memberships WHERE MembershipId=@Id;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.GetBadges @UserIdsJson nvarchar(2000) AS
BEGIN
 SET NOCOUNT ON;
 SELECT TRY_CONVERT(int,j.value) AS UserId,CAST(dbo.IsPro(TRY_CONVERT(int,j.value)) AS bit) AS IsPro FROM OPENJSON(@UserIdsJson) j WHERE TRY_CONVERT(int,j.value) IS NOT NULL;
END;');
